using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnPlayerCorruptAfflictionOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/OnPlayerCorruptAffliction Omen Data")]
public class OnPlayerCorruptAfflictionOmenData : OmenData
{
	private const string wheneverCorruptAfflictionChantID = "CorruptAfflictionChant";

	private const string corruptAfflictionMinimunChantID = "CorruptAfflictionMinimunChant";

	[Header("On Player Corrupt Affliction Omen Data")]
	[SerializeField]
	private int minimunCorruptAfflictionAmount;

	protected bool IsMinimunCorruptAmount(int corruptAfflictionAmount)
	{
		return corruptAfflictionAmount >= minimunCorruptAfflictionAmount;
	}

	public override string OmenConvertedDescription()
	{
		string text = "";
		text = ((minimunCorruptAfflictionAmount > 1) ? Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("CorruptAfflictionMinimunChant"), minimunCorruptAfflictionAmount) : ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("CorruptAfflictionChant"));
		return text + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + base.OmenConvertedDescription();
	}
}
